select *, max(cost) over (partition by order_id order by delivered_date, id rows between 6 preceding and current row) as last7_max_cost, avg(cost) over (partition by order_id order by delivered_date, id rows between 6 preceding and current row) as last7_avg_cost, count(cost) over (partition by order_id order by delivered_date, id rows between 6 preceding and current row) as last7_count_cost, sum(cost) over (partition by order_id order by delivered_date, id rows between 6 preceding and current row) as last7_sum_cost from shipments
